\set ON_ERROR_STOP on
BEGIN;
INSERT INTO auth.users(id,email) VALUES('17000000-0000-4000-8000-000000000001','pipelineadmin@simisrl.eu') ON CONFLICT DO NOTHING;
UPDATE public.profiles SET role='admin',active=true WHERE id='17000000-0000-4000-8000-000000000001';
INSERT INTO public.companies(id,company_type,business_name) VALUES('27000000-0000-4000-8000-000000000001','customer','Pipeline customer') ON CONFLICT DO NOTHING;
INSERT INTO public.invoices(id,invoice_type,invoice_number,legal_entity_id,customer_id,amount_total,amount_net,currency) SELECT '68000000-0000-4000-8000-000000000001','sale','PIPE-INV',(SELECT id FROM public.legal_entities WHERE code='SIMI-IT'),'27000000-0000-4000-8000-000000000001',1,1,'EUR' ON CONFLICT DO NOTHING;
INSERT INTO public.projects(id,project_code,name,legal_entity_id) SELECT '37000000-0000-4000-8000-000000000001','PIPE-1','Pipeline project',id FROM public.legal_entities WHERE code='SIMI-IT' ON CONFLICT DO NOTHING;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','17000000-0000-4000-8000-000000000001',true);
DO $$ DECLARE e uuid; o uuid; c uuid; ord uuid; inv uuid; BEGIN SELECT id INTO e FROM public.legal_entities WHERE code='SIMI-IT'; o:=public.save_offer(jsonb_build_object('offer_number','OFF-PIPE','revision',0,'legal_entity_id',e,'counterparty_id','27000000-0000-4000-8000-000000000001','currency','EUR','status','accepted','project_ids',jsonb_build_array('37000000-0000-4000-8000-000000000001'),'lines',jsonb_build_array(jsonb_build_object('description','Servizio','quantity',100,'unit_price',10,'discount',10,'vat_rate',22)))); IF (SELECT amount_net FROM public.offers WHERE id=o)<>900 OR (SELECT amount_total FROM public.offers WHERE id=o)<>1098 THEN RAISE EXCEPTION 'offer totals'; END IF; c:=public.save_contract(jsonb_build_object('reference','CTR-PIPE','title','Contratto pipeline','legal_entity_id',e,'counterparty_id','27000000-0000-4000-8000-000000000001','expires_at',CURRENT_DATE+30,'project_ids',jsonb_build_array('37000000-0000-4000-8000-000000000001'))); IF NOT EXISTS(SELECT 1 FROM public.contract_projects WHERE contract_id=c) OR NOT EXISTS(SELECT 1 FROM public.deadlines WHERE contract_id=c) THEN RAISE EXCEPTION 'contract relations/deadline'; END IF; ord:=public.save_order(jsonb_build_object('order_number','PIPE-ORD','order_type','sale','status','confirmed','legal_entity_id',e,'counterparty_id','27000000-0000-4000-8000-000000000001','order_date',CURRENT_DATE,'currency','EUR','lines',jsonb_build_array(jsonb_build_object('description','Servizio','quantity',1,'unit_price',1)))); SELECT id INTO inv FROM public.invoices WHERE invoice_number='PIPE-INV'; PERFORM public.set_offer_order(o,ord,true); PERFORM public.set_contract_order(c,ord,true); IF NOT EXISTS(SELECT 1 FROM public.offer_orders WHERE offer_id=o AND order_id=ord) OR NOT EXISTS(SELECT 1 FROM public.contract_orders WHERE contract_id=c AND order_id=ord) THEN RAISE EXCEPTION 'relation actions'; END IF; IF inv IS NOT NULL THEN PERFORM public.set_contract_invoice(c,inv,true); END IF; END $$;
RESET ROLE;
\echo 'PASS: 1F.2 offers revisions, discount totals, contracts, projects and derived deadline'
ROLLBACK;
